package api

import (
	"net/http"
	"strconv"
	"time"

	"github.com/tidewater-labs/ferrydesk/internal/pricing"
)

type farePreviewResponse struct {
	Route string  `json:"route"`
	Total float64 `json:"total"`
}

func (h *Handlers) farePreview(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	route := q.Get("route")
	adults, err1 := strconv.Atoi(q.Get("adults"))
	children, err2 := strconv.Atoi(q.Get("children"))
	if route == "" || err1 != nil || err2 != nil || adults < 0 || children < 0 || adults+children == 0 {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "route, adults and children are required"})
		return
	}
	sls, err := h.svc.Sailings(r.Context(), route, time.Now(), time.Now().Add(30*24*time.Hour))
	if err != nil || len(sls) == 0 {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "no upcoming sailings"})
		return
	}
	total := pricing.Fare(pricing.Route{Code: route, AdultFare: sls[0].AdultFare}, pricing.Passengers{Adults: adults, Children: children})
	writeJSON(w, http.StatusOK, farePreviewResponse{Route: route, Total: float64(total) / 100})
}

