import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestFarePreviewRejectsMissingParams(t *testing.T) {
	h := &Handlers{}
	rec := httptest.NewRecorder()
	h.farePreview(rec, httptest.NewRequest(http.MethodGet, "/fares/preview?route=WLG-PCN", nil))
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("code = %d", rec.Code)
	}
	var body map[string]string
	_ = json.NewDecoder(rec.Body).Decode(&body)
	if body["error"] == "" {
		t.Fatal("want error message")
	}
}

